"""Real native HTTP downloads sharing one cap; generated bytes, localhost only."""
import functools
import http.server
import os
from pathlib import Path
import sys
import subprocess
import tempfile
import threading
import time
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'src'))
from core.queue_manager import DownloadManager
from core.downloader import _download_single


class QuietHandler(http.server.SimpleHTTPRequestHandler):
    def log_message(self, *_):
        pass


class LocalBandwidthTests(unittest.TestCase):
    def test_native_hls_parallel_fragments_share_budget(self):
        bin_dir = Path(os.environ['APPDATA']) / 'YoutubePro' / 'bin'
        if not (bin_dir / 'ffmpeg.exe').is_file():
            self.skipTest('FFmpeg missing')
        with tempfile.TemporaryDirectory(dir=ROOT) as directory:
            base = Path(directory)
            source = base / 'source'
            source.mkdir()
            subprocess.run([str(bin_dir / 'ffmpeg.exe'), '-hide_banner', '-loglevel', 'error',
                            '-f', 'lavfi', '-i', 'testsrc2=size=320x180:rate=15', '-t', '5', '-an',
                            '-c:v', 'libx264', '-preset', 'ultrafast', '-b:v', '600k', '-g', '15',
                            '-hls_time', '1', '-hls_playlist_type', 'vod', '-hls_segment_filename',
                            str(source / 'segment-%03d.ts'), str(source / 'list.m3u8')], check=True, timeout=20)
            size = sum(file.stat().st_size for file in source.glob('*.ts'))
            server = http.server.ThreadingHTTPServer(('127.0.0.1', 0), functools.partial(QuietHandler, directory=str(source)))
            server_thread = threading.Thread(target=server.serve_forever, daemon=True)
            server_thread.start()
            manager = DownloadManager()
            try:
                manager.configure('manual', 1, 100000)
                started = time.monotonic()
                with patch('core.queue_manager.show_notification'):
                    manager.submit([f'http://127.0.0.1:{server.server_port}/list.m3u8'],
                                   {'format': 'video', 'quality': '720p'}, str(base / 'out'), str(bin_dir))
                    result = manager.wait(30)
                elapsed = time.monotonic() - started
                self.assertEqual(result['status'], 'finished_all', result['error'])
                self.assertGreaterEqual(elapsed, size / 100000 - 0.3)
                self.assertTrue(list((base / 'out').glob('*.mp4')))
                print(f'HLS {size} bytes / 3 parallel fragments at 100000 B/s: {elapsed:.2f}s')
            finally:
                manager.close()
                server.shutdown()
                server.server_close()
                server_thread.join(timeout=3)

    def test_pause_resume_real_http_preserves_budget_and_job(self):
        with tempfile.TemporaryDirectory(dir=ROOT) as directory:
            base = Path(directory)
            source = base / 'source'
            source.mkdir()
            payload = b'y' * 400000
            (source / 'resume.mp4').write_bytes(payload)
            server = http.server.ThreadingHTTPServer(('127.0.0.1', 0), functools.partial(QuietHandler, directory=str(source)))
            server_thread = threading.Thread(target=server.serve_forever, daemon=True)
            server_thread.start()
            def worker(url, opts, path, request, folder):
                opts.update(postprocessors=[], quiet=True, noprogress=True)
                return _download_single(url, opts, path, request, folder)
            manager = DownloadManager(worker)
            try:
                manager.configure('manual', 1, 200000)
                url = f'http://127.0.0.1:{server.server_port}/resume.mp4'
                manager.submit([url], {'format': 'video', 'quality': '720p', 'embed_subs': True}, str(base / 'out'))
                deadline = time.monotonic() + 10
                while sum(n for _, n in manager.samples) < 50000:
                    self.assertLess(time.monotonic(), deadline)
                    time.sleep(0.02)
                identity = manager.jobs[0].id
                manager.pause(url)
                while manager.jobs[0].future is not None:
                    self.assertLess(time.monotonic(), deadline)
                    time.sleep(0.02)
                self.assertEqual(manager.snapshot()['status'], 'paused')
                self.assertTrue(list((base / 'out').glob('*.part')))
                manager.resume(url)
                with patch('core.queue_manager.show_notification'):
                    result = manager.wait(15)
                self.assertEqual(result['status'], 'finished_all', result['error'])
                self.assertEqual(result['items'][0]['id'], identity)
                self.assertEqual(manager.budget.rate, 200000)
                self.assertTrue(manager.jobs[0].options['embed_subs'])
                files = list((base / 'out').glob('*.mp4'))
                self.assertEqual(len(files), 1)
                self.assertEqual(files[0].read_bytes(), payload)
            finally:
                manager.close()
                server.shutdown()
                server.server_close()
                server_thread.join(timeout=3)

    def test_two_real_downloads_share_100000_bytes_per_second(self):
        with tempfile.TemporaryDirectory(dir=ROOT) as directory:
            base = Path(directory)
            source = base / 'source'
            source.mkdir()
            payload = b'x' * 200000
            for name in ('a.mp4', 'b.mp4'):
                (source / name).write_bytes(payload)
            server = http.server.ThreadingHTTPServer(('127.0.0.1', 0), functools.partial(QuietHandler, directory=str(source)))
            server_thread = threading.Thread(target=server.serve_forever, daemon=True)
            server_thread.start()
            def worker(url, opts, path, request, folder):
                # These are transport fixtures, not valid media. Skip FFmpeg probing.
                opts['postprocessors'] = []
                opts.update(quiet=True, noprogress=True)
                return _download_single(url, opts, path, request, folder)
            manager = DownloadManager(worker)
            try:
                manager.configure('manual', 2, 100000)
                urls = [f'http://127.0.0.1:{server.server_port}/{name}' for name in ('a.mp4', 'b.mp4')]
                started = time.monotonic()
                with patch('core.queue_manager.show_notification'):
                    manager.submit(urls, {'format': 'video', 'quality': '720p'}, str(base / 'output'))
                    result = manager.wait(20)
                elapsed = time.monotonic() - started
                self.assertEqual(result['status'], 'finished_all', result['error'])
                files = list((base / 'output').rglob('*.mp4'))
                self.assertEqual(len(files), 2)
                for file in files:
                    self.assertEqual(file.read_bytes(), payload)
                # 400000 bytes / 100000 B/s = at least ~4 seconds in aggregate,
                # rather than two independent caps finishing in ~2 seconds.
                self.assertGreaterEqual(elapsed, 3.8)
                self.assertLess(elapsed, 15)
                print(f'Combined 400000-byte transfer at 100000 B/s: {elapsed:.2f}s')
            finally:
                manager.close()
                server.shutdown()
                server.server_close()
                server_thread.join(timeout=3)


if __name__ == '__main__':
    unittest.main()
